INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13240, 'plPL', 'Timear widzi w twojej przyszłości Konstrukty wirówki!', 'Musisz udać się do Okulusa unoszącego się nad Mrozarrą, $N.$B$BPrzewidziałem sytuację, w której musisz zniszczyć znajdujące się tam konstrukty wirówki. Zapewniam cię, że jeśli najpierw nie wyeliminujesz tych magicznych tworów, ty i twoi przyjaciele poniesiecie porażkę.$B$BTak ujrzałem, tak musisz uczynić.', 'Arcymag Timear w Dalaranie przewidział, że musisz zniszczyć 10 konstruktów wirówki.', '', 'Wróć do arcymaga Timeara w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13241, 'plPL', 'Timear widzi w twojej przyszłości Berserkerów Ymirjarów!', 'W niedalekiej przyszłości między tobą a zwycięstwem staną czempioni króla Ymirona.$B$BUdasz się do twierdzy zwanej Iglicą Utgard, ukrytej głęboko w lasach Wyjącego Fiordu. Nie potrafię dość mocno podkreślić, jak ważne jest, byś ty i twoi towarzysze podróży rozprawili się z berserkerami Ymirjarów, którzy tam przebywają.$B$BJeśli tego nie zrobicie, może to oznaczać twoją zgubę, $N!', 'Arcymag Timear w Dalaranie chce, żebyś $gzabił:zabiła; 7 berserkerów Ymirjarów.', '', 'Wróć do arcymaga Timeara w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13243, 'plPL', 'Timear widzi w twojej przyszłości Agentów Nieskończoności!', 'Linii czasu zagraża Nieskończone Stado. Bez twojej interwencji cały czas się rozpadnie!$B$BMusisz udać się do punktu w czasie znanego jako Rzeź Stratholmu, w Jaskiniach Czasu.$B$BSama próba wejrzenia we wszystkie możliwe przeszłości przyprawia mnie o migrenę, ale wiem jedno: to niezwykle ważne, byś $gzabił:zabiła; agentów Nieskończonego Stada.$B$BTylko ich śmierć ocali prawdziwą przeszłość i nie pozwoli, by teraźniejszość i przyszłość zostały na zawsze unicestwione!', 'Arcymag Timear w Dalaranie przewidział, że musisz zabić 4 agentów Nieskończonego Stada.', '', 'Wróć do arcymaga Timeara w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13244, 'plPL', 'Timear widzi w twojej przyszłości Tytanowych Awangardzistów!', 'Całe Azeroth jest w niebezpieczeństwie. Szalony bóg Loken ma moc, by położyć wszystkiemu kres!$B$BW Ziemskiej Strażnicy w Salach Błyskawic tytanowi awangardziści czekają w gotowości, by wykonać straszliwą wolę Lokena na niezliczonych, niczego nieświadomych ofiarach.$B$BPrzyszłość mi się objawiła, $N. To ty masz sprawić, by do tego nie doszło!', 'Arcymag Timear w Dalaranie przewidział, że musisz zabić 7 tytanowych awangardzistów.', '', 'Wróć do arcymaga Timeara w Lesie Kryształowej Pieśni.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13244, 'plPL', 'Wszyscy jesteśmy twoimi dłużnikami, $N.$b$bJeśli cokolwiek jest pewne, to to, że nas nie $gzawiodłeś:zawiodłaś; i nie zawiedziesz w przyszłości!', 0),
(13253, 'plPL', '<Arcymag Lan\'dalock wzdycha z ulgą.>$b$bSzczerze mówiąc, obawiałem się najgorszego. Trudno stać bezczynnie, gdy inni, tacy jak ty, mierzą się ze sprawami życia i śmierci, które – jak się zdaje – codziennie zagrażają naszemu światu.$b$bCo my teraz zrobimy z tym gigantycznym pierścieniem?', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13244, 'plPL', 'Nawet ja nie potrafię dociec, czemu stoimy tu i rozmawiamy, skoro jeszcze nie $gzażegnałeś:zażegnałaś; zagrożenia ze strony tytanowych awangardzistów.', 0),
(13253, 'plPL', 'Znowu rozmawiamy, $n. Czy to znaczy, że jesteśmy bezpieczni przed szaleństwem Lokena, czy też czeka nas zguba?', 0);
