INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(29832, 'plPL', '%s przyjmuje Postawę bojową!', '', 0),
(29833, 'plPL', '%s przyjmuje Postawę berserkera!', '', 0),
(29834, 'plPL', '%s przyjmuje Postawę defensywną!', '', 0),
(29865, 'plPL', '%s zaczyna rzucać Rozbłysk błyskawic!', '', 0),
(30528, 'plPL', 'Chcecie stanąć przed panem? Najpierw musicie przetrwać burzę!', '', 0),
(30529, 'plPL', 'Najmniejsza iskra będzie waszą zgubą.', '', 0),
(30530, 'plPL', 'Nikt nie jest bezpieczny!', '', 0),
(30531, 'plPL', 'Porażające, wiem.', '', 0),
(30532, 'plPL', 'Porywacie się na niemożliwe.', '', 0),
(30533, 'plPL', 'Wasza iskra życia... zgasła.', '', 0),
(30534, 'plPL', 'Panie... masz gości.', '', 0),
(30535, 'plPL', 'Jaka nadzieja wam pozostała? Żadna!', '', 0),
(30536, 'plPL', 'Byłem świadkiem powstania i upadku imperiów... narodzin i wymarcia całych gatunków... Przez niezliczone tysiąclecia jedyną stałą pozostawała głupota śmiertelników. Wasza obecność tutaj to potwierdza.', '', 0),
(30537, 'plPL', 'Mój pan ukazał mi przyszłość i nie ma w niej dla was miejsca. Azeroth odrodzi się w ciemności. Yogg-Saron zostanie uwolniony! Panteon upadnie!', '', 0),
(30538, 'plPL', 'Nie ukryjecie się przed przeznaczeniem!', '', 0),
(30539, 'plPL', 'Podejdźcie bliżej. Zrobię to szybko.', '', 0),
(30540, 'plPL', 'Wasze ciało nie wytrzyma długo.', '', 0),
(30541, 'plPL', 'Tylko śmiertelnik...', '', 0),
(30542, 'plPL', 'Ja... jestem... WIECZNY!', '', 0),
(30543, 'plPL', 'Zmarnowaliście tę odrobinę czasu, jaką mieliście!', '', 0),
(30544, 'plPL', 'Moja śmierć... zwiastuje koniec tego świata.', '', 0),
(30545, 'plPL', 'Wpatrujecie się ślepo w otchłań!', '', 0),
(30546, 'plPL', 'Wasza ignorancja jest bezdenna. Czy nie widzicie, dokąd prowadzi ta ścieżka?', '', 0),
(30547, 'plPL', 'Stoicie na krawędzi zapomnienia!', '', 0),
(31407, 'plPL', 'Jestem największym z synów mego ojca! Nadszedł wasz koniec!', '', 0),
(31408, 'plPL', 'Pokażcie, na co was stać!', '', 0),
(31409, 'plPL', 'Brońcie się, choć na niewiele wam się to zda!', '', 0),
(31410, 'plPL', 'GRAAAAAH! Ujrzyjcie furię żelaza i stali!', '', 0),
(31411, 'plPL', 'Tak kończy się wasza klątwa.', '', 0),
(31412, 'plPL', 'Ciało... jest... słabe!', '', 0),
(31414, 'plPL', 'Jak to możliwe...? Ciało nie jest... silniejsze!', '', 0);
